/* enemies.js — 4 tipos, FSM (idle→chase→attack→death), LOS aggro, drops.
 * Modelos: cada inimigo é um THREE.Group de primitivas low-poly (torso, cabeça,
 * 2 braços, 2 pernas) com pivôs por membro — geometria compartilhada, materiais
 * clonados por inimigo (flash independente).
 * Animação procedural no update (sem libs externas): idle (respiração + sway de
 * cabeça), chase (ciclo de caminhada + lean), attack (lunge/recuo + braços),
 * death (tombar + afundar + fade).
 * AI: perseguição com aceleração (sem snap), distância preferida para ranged,
 * strafe leve, separação suave entre inimigos e colisão com paredes via circleFree.
 * Hit feedback: flash + flinch de escala + knockback curto (dano/hp intactos).
 */
import * as THREE from 'three';
import { C } from './constants.js';
import { hasLOS, dist2D } from './map.js';
import { circleFree } from './move.js';

const { zombie, imp, demon, baron } = C.ENEMIES;

const DEATH_FALL = 0.35; // s para tombar no chão
const DEATH_SINK = 0.55; // s para afundar + fade

const BASE_COLOR = {
  zombie: zombie.color,
  imp: imp.color,
  demon: demon.color,
  baron: baron.color,
};

export function createEnemies(scene, map, hooks) {
  const list = [];

  const geo = {
    zombie: buildZombieGeo(),
    imp: buildImpGeo(),
    demon: buildDemonGeo(),
    baron: buildBaronGeo(),
  };

  const R = (lo, hi) => lo + Math.random() * (hi - lo);

  /* ---- construtores de malha (pivô por membro para animação) ---------------- */

  function mat(color) {
    return new THREE.MeshBasicMaterial({ color });
  }

  // Pivô no "ombro"/"quadril": o membro pendura para baixo; rotacionar o pivô
  // em z balança o membro p/ frente/trás (a frente do modelo é +X local).
  function limb(w, h, d, m, jointY, zOff) {
    const g = new THREE.Group();
    g.position.set(0, jointY, zOff);
    const box = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m);
    box.position.y = -h / 2;
    g.add(box);
    return g;
  }

  function box(w, h, d, m, x, y, z) {
    const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m);
    b.position.set(x, y, z);
    return b;
  }

  function horn(r, h, seg, m, x, y, z) {
    const c = new THREE.Mesh(new THREE.ConeGeometry(r, h, seg), m);
    c.position.set(x, y, z);
    return c;
  }

  function buildZombieGeo() {
    const g = new THREE.Group();
    const body = new THREE.Group();
    body.name = 'body';
    g.add(body);
    const bm = mat(BASE_COLOR.zombie), sm = mat(0x9a9088);
    const torso = box(0.5, 0.55, 0.3, bm, 0, 0.95, 0);
    torso.rotation.z = -0.18; // corcunda p/ frente
    torso.name = 'torso';
    const head = box(0.26, 0.26, 0.26, sm, 0, 1.45, 0.14);
    head.name = 'head';
    const armL = limb(0.13, 0.5, 0.15, bm, 1.18, 0.31);
    armL.name = 'armL';
    const armR = limb(0.13, 0.5, 0.15, bm, 1.18, -0.31);
    armR.name = 'armR';
    const legL = limb(0.16, 0.66, 0.18, bm, 0.66, 0.13);
    legL.name = 'legL';
    const legR = limb(0.16, 0.66, 0.18, bm, 0.66, -0.13);
    legR.name = 'legR';
    body.add(torso, head, armL, armR, legL, legR);
    return g;
  }

  function buildImpGeo() {
    const g = new THREE.Group();
    const body = new THREE.Group();
    body.name = 'body';
    g.add(body);
    const bm = mat(BASE_COLOR.imp), sm = mat(0xa04a35), hm = mat(0xccaa66);
    const torso = box(0.42, 0.6, 0.3, bm, 0, 0.95, 0);
    torso.rotation.z = -0.12;
    torso.name = 'torso';
    const head = box(0.3, 0.3, 0.28, sm, 0, 1.5, 0.06);
    head.name = 'head';
    const hornL = horn(0.06, 0.24, 4, hm, -0.11, 0.27, 0.02);
    hornL.name = 'hornL';
    const hornR = hornL.clone();
    hornR.position.x = 0.11;
    hornR.name = 'hornR';
    head.add(hornL, hornR);
    const armL = limb(0.12, 0.55, 0.14, bm, 1.18, 0.27);
    armL.name = 'armL';
    const armR = limb(0.12, 0.55, 0.14, bm, 1.18, -0.27);
    armR.name = 'armR';
    const legL = limb(0.14, 0.58, 0.16, bm, 0.58, 0.11);
    legL.name = 'legL';
    const legR = limb(0.14, 0.58, 0.16, bm, 0.58, -0.11);
    legR.name = 'legR';
    body.add(torso, head, armL, armR, legL, legR);
    return g;
  }

  function buildDemonGeo() {
    const g = new THREE.Group();
    const body = new THREE.Group();
    body.name = 'body';
    g.add(body);
    const bm = mat(BASE_COLOR.demon), sm = mat(0xc04080), jm = mat(0xe080b0);
    const torso = box(0.72, 0.5, 0.42, bm, 0, 0.62, 0);
    torso.rotation.z = 0.05; // postura de touro, cabeça à frente
    torso.name = 'torso';
    const head = box(0.44, 0.36, 0.32, sm, 0, 1.05, 0.16);
    head.name = 'head';
    const jaw = box(0.36, 0.1, 0.28, jm, 0, 0.84, 0.32);
    jaw.name = 'jaw';
    const armL = limb(0.18, 0.42, 0.2, bm, 0.8, 0.45);
    armL.name = 'armL';
    const armR = limb(0.18, 0.42, 0.2, bm, 0.8, -0.45);
    armR.name = 'armR';
    const legL = limb(0.2, 0.5, 0.22, bm, 0.5, 0.2);
    legL.name = 'legL';
    const legR = limb(0.2, 0.5, 0.22, bm, 0.5, -0.2);
    legR.name = 'legR';
    body.add(torso, head, jaw, armL, armR, legL, legR);
    return g;
  }

  function buildBaronGeo() {
    const g = new THREE.Group();
    const body = new THREE.Group();
    body.name = 'body';
    g.add(body);
    const bm = mat(BASE_COLOR.baron), sm = mat(0x3a8a44), hm = mat(0xddcc88);
    const torso = box(0.6, 0.85, 0.4, bm, 0, 1.05, 0);
    torso.rotation.z = -0.08;
    torso.name = 'torso';
    const head = box(0.36, 0.4, 0.36, sm, 0, 1.75, 0.06);
    head.name = 'head';
    const hornL = horn(0.07, 0.34, 4, hm, -0.13, 0.37, 0.02);
    hornL.name = 'hornL';
    const hornR = hornL.clone();
    hornR.position.x = 0.13;
    hornR.name = 'hornR';
    head.add(hornL, hornR);
    const armL = limb(0.18, 0.62, 0.2, bm, 1.42, 0.36);
    armL.name = 'armL';
    const armR = limb(0.18, 0.62, 0.2, bm, 1.42, -0.36);
    armR.name = 'armR';
    const legL = limb(0.2, 0.72, 0.22, bm, 0.72, 0.16);
    legL.name = 'legL';
    const legR = limb(0.2, 0.72, 0.22, bm, 0.72, -0.16);
    legR.name = 'legR';
    body.add(torso, head, armL, armR, legL, legR);
    return g;
  }

  function collectParts(mesh) {
    const p = {};
    mesh.traverse((o) => { if (o.name) p[o.name] = o; });
    return p;
  }

  function collectMeshes(mesh) {
    const out = [];
    mesh.traverse((o) => { if (o.isMesh) out.push(o); });
    return out;
  }

  function spawnFromMap() {
    for (const e of map.enemies) {
      const cfg = C.ENEMIES[e.type];
      const mesh = geo[e.type].clone();
      // Materiais únicos por inimigo: flash/flinch não vazam entre clones.
      mesh.traverse((o) => {
        if (o.isMesh) {
          o.material = o.material.clone();
          o.material.userData.baseColor = o.material.color.getHex();
        }
      });
      mesh.position.set(e.x, 0, e.z);
      mesh.visible = true;
      scene.add(mesh);
      const parts = collectParts(mesh);
      const en = {
        type: e.type, x: e.x, z: e.z, y: 0,
        hp: cfg.hp,
        speed: cfg.speed,
        state: 'idle',
        cooldown: Math.random() * 1,
        facing: Math.random() * Math.PI * 2,
        mesh,
        dead: false,
        aggroed: false,
        flashT: 0,
        attackFlash: 0,
        attackT: 0,
        attackDur: 1,
        flinch: 0,
        animT: Math.random() * 10,
        walkT: Math.random() * 10,
        bob: 0,
        vx: 0, vz: 0,
        kbT: 0, kbDur: 0.18, kbDirX: 0, kbDirZ: 0, kbSpeed: 0,
        deathT: 0,
        lean: parts.torso.rotation.z,
        parts,
        flashables: collectMeshes(mesh),
      };
      en.takeDamage = (dmg) => damageEnemy(en, dmg);
      list.push(en);
    }
  }

  /* ---- dano / hit feedback (mesmo fluxo de dano e kill de sempre) ------------ */

  function damageEnemy(en, dmg) {
    if (en.dead) return;
    en.hp -= dmg;
    en.flashT = 0.08;
    if (en.hp <= 0) {
      en.dead = true;
      en.state = 'death';
      en.deathT = 0;
      hooks.onKill(en, en.x, en.z);
    } else {
      en.flinch = 0.12; // flinch de escala
      // knockback curto para longe do atirador (jogador)
      const pl = hooks.getPlayer();
      const dx = en.x - pl.x, dz = en.z - pl.z;
      const d = Math.hypot(dx, dz) || 1;
      en.kbDirX = dx / d;
      en.kbDirZ = dz / d;
      en.kbSpeed = Math.min(8, 3.5 + dmg * 0.05);
      en.kbDur = 0.18;
      en.kbT = 0.18;
      if (!en.aggroed) {
        en.aggroed = true; // dano sempre aggra
        en.state = 'chase';
      }
    }
  }

  /* ---- ataques (inalterados em comportamento) -------------------------------- */

  function fireball(en) {
    const pl = hooks.getPlayer();
    const dx = pl.x - en.x, dz = pl.z - en.z;
    hooks.spawnFireball(en.x, en.y + 1.4, en.z, dx, dz, 'enemy');
  }

  function hitscanZombie(en) {
    const pl = hooks.getPlayer();
    const dx = pl.x - en.x, dz = pl.z - en.z;
    const d = Math.hypot(dx, dz);
    if (d > 0.01 && !hasLOS(map, Math.floor(en.z), Math.floor(en.x), Math.floor(pl.z), Math.floor(pl.x))) return false;
    hooks.damagePlayer(R(zombie.damageMin, zombie.damageMax));
    return true;
  }

  /* ---- movimento: aceleração, parede, strafe, separação ---------------------- */

  function moveWithCollision(en, dt) {
    const nx = en.x + en.vx * dt;
    if (circleFree(map, nx, en.z, 0.35)) en.x = nx; else en.vx = 0;
    const nz = en.z + en.vz * dt;
    if (circleFree(map, en.x, nz, 0.35)) en.z = nz; else en.vz = 0;
  }

  function steer(en, pl, dt, back, scale = 1) {
    const cfg = C.ENEMIES[en.type];
    const dx = pl.x - en.x, dz = pl.z - en.z;
    const d = Math.hypot(dx, dz) || 1;
    let dirX = dx / d, dirZ = dz / d;
    if (back) { dirX = -dirX; dirZ = -dirZ; }
    if (en.type !== 'demon') {
      // strafe perpendicular suave
      const s = Math.sin(en.animT * 0.6) * 0.5;
      dirX += -dz / d * s;
      dirZ += dx / d * s;
    }
    const len = Math.hypot(dirX, dirZ) || 1;
    dirX /= len; dirZ /= len;
    const k = 1 - Math.exp(-6 * dt); // suavização de aceleração
    const spd = cfg.speed * scale;
    en.vx += (dirX * spd - en.vx) * k;
    en.vz += (dirZ * spd - en.vz) * k;
    moveWithCollision(en, dt);
  }

  function strafeInPlace(en, pl, dt) {
    const dx = pl.x - en.x, dz = pl.z - en.z;
    const d = Math.hypot(dx, dz) || 1;
    const s = Math.sin(en.animT * 0.7);
    let dirX = -dz / d * s, dirZ = dx / d * s;
    const len = Math.hypot(dirX, dirZ) || 1;
    dirX /= len; dirZ /= len;
    const k = 1 - Math.exp(-2.5 * dt);
    const spd = C.ENEMIES[en.type].speed * 0.35;
    en.vx += (dirX * spd - en.vx) * k;
    en.vz += (dirZ * spd - en.vz) * k;
    moveWithCollision(en, dt);
  }

  function applyKnockback(en, dt) {
    if (en.kbT <= 0) return;
    en.kbT -= dt;
    const f = Math.max(0, en.kbT / en.kbDur);
    const kx = en.kbDirX * en.kbSpeed * f * dt;
    const kz = en.kbDirZ * en.kbSpeed * f * dt;
    if (circleFree(map, en.x + kx, en.z, 0.35)) en.x += kx;
    if (circleFree(map, en.x, en.z + kz, 0.35)) en.z += kz;
  }

  function separate(en, list, dt) {
    for (const o of list) {
      if (o === en || o.dead) continue;
      const dx = en.x - o.x, dz = en.z - o.z;
      const d = Math.hypot(dx, dz);
      if (d > 0.0001 && d < 0.9) {
        const push = (0.9 - d) * 1.6 * dt;
        const px = dx / d * push, pz = dz / d * push;
        if (circleFree(map, en.x + px, en.z, 0.35)) en.x += px;
        if (circleFree(map, en.x, en.z + pz, 0.35)) en.z += pz;
      }
    }
  }

  /* ---- animações (todas procedurais, no update) ------------------------------ */

  function applyFlash(en) {
    const on = en.flashT > 0 || en.attackFlash > 0;
    for (const o of en.flashables) o.material.color.setHex(on ? 0xffffff : o.material.userData.baseColor);
  }

  function applyFlinch(en) {
    const f = en.flinch > 0 ? en.flinch / 0.12 : 0;
    en.parts.body.scale.set(1 + f * 0.12, 1 - f * 0.12, 1 + f * 0.12);
  }

  function animate(en, dt, moving) {
    const t = en.animT, parts = en.parts;
    const lean = en.lean;
    let bob = 0;
    if (en.attackT > 0) {
      const AP = 1 - en.attackT / en.attackDur;
      parts.legL.rotation.z = 0;
      parts.legR.rotation.z = 0;
      if (en.type === 'demon') {
        const sw = Math.sin(Math.min(1, AP) * Math.PI);
        parts.armL.rotation.z = sw * 1.4;
        parts.armR.rotation.z = sw * 1.4;
        parts.body.position.x = sw * 0.3; // lunge p/ frente
        parts.torso.rotation.z = lean + sw * 0.15;
      } else if (en.type === 'zombie') {
        const raise = AP < 0.6 ? AP / 0.6 : Math.max(0, 1 - (AP - 0.6) / 0.4);
        parts.armL.rotation.z = raise * 1.7;
        parts.armR.rotation.z = raise * 1.7;
        parts.body.position.x = 0;
        parts.torso.rotation.z = lean - raise * 0.1;
      } else {
        // imp/baron: ergue os braços (bola de fogo) e recua
        const wind = Math.min(1, AP * 2.5);
        const release = Math.max(0, (AP - 0.45) / 0.55);
        const arm = wind * (1 - release);
        parts.armL.rotation.z = arm * 1.9;
        parts.armR.rotation.z = arm * 1.9;
        parts.body.position.x = wind * 0.1;
        parts.torso.rotation.z = lean - wind * 0.12;
      }
      bob = Math.sin(t * 14) * 0.01;
    } else if (moving) {
      en.walkT += dt * 3 * en.speed;
      const w = en.walkT;
      const sw = 0.55;
      parts.legL.rotation.z = Math.sin(w) * sw;
      parts.legR.rotation.z = -Math.sin(w) * sw;
      parts.armL.rotation.z = -Math.sin(w) * sw * 0.7;
      parts.armR.rotation.z = Math.sin(w) * sw * 0.7;
      parts.torso.rotation.z = lean - 0.06 + Math.sin(w * 2) * 0.04;
      parts.body.position.x = 0;
      bob = Math.abs(Math.sin(w)) * 0.05;
    } else {
      const settle = Math.min(1, dt * 8);
      parts.legL.rotation.z += (0 - parts.legL.rotation.z) * settle;
      parts.legR.rotation.z += (0 - parts.legR.rotation.z) * settle;
      parts.armL.rotation.z += (0 - parts.armL.rotation.z) * settle;
      parts.armR.rotation.z += (0 - parts.armR.rotation.z) * settle;
      parts.torso.rotation.z += (lean + Math.sin(t * 2) * 0.02 - parts.torso.rotation.z) * Math.min(1, dt * 5);
      parts.body.position.x += (0 - parts.body.position.x) * settle;
      bob = Math.sin(t * 2) * 0.02;
    }
    // sway de cabeça sempre presente (vivo)
    parts.head.rotation.y = Math.sin(t * 1.3) * 0.12;
    parts.head.rotation.x = Math.sin(t * 1.1) * 0.04;
    en.bob = bob;
  }

  function animateDeath(en, dt) {
    en.deathT += dt;
    const T = en.deathT;
    if (T < 0.01) {
      for (const o of en.flashables) o.material.transparent = true;
    }
    const fall = Math.min(1, T / DEATH_FALL);
    const ease = 1 - Math.pow(1 - fall, 3);
    en.mesh.rotation.z = -Math.PI / 2 * ease; // tomba p/ frente (frente = +X local)
    if (T > DEATH_FALL) {
      const sink = Math.min(1, (T - DEATH_FALL) / DEATH_SINK);
      en.mesh.position.y = en.y - sink * 0.6;
      const a = 1 - sink;
      for (const o of en.flashables) o.material.opacity = Math.max(0, a);
    }
    if (T >= DEATH_FALL + DEATH_SINK) en.mesh.visible = false;
  }

  function setPos(en) {
    en.mesh.position.set(en.x, en.y + en.bob, en.z);
    en.mesh.rotation.y = en.facing;
  }

  /* ---- loop principal -------------------------------------------------------- */

  function update(dt) {
    const pl = hooks.getPlayer();
    for (const en of list) {
      en.animT += dt;
      if (en.dead) { animateDeath(en, dt); continue; }

      en.flashT -= dt;
      en.attackFlash = Math.max(0, en.attackFlash - dt);
      en.flinch = Math.max(0, en.flinch - dt);
      if (en.attackT > 0) en.attackT -= dt;

      const cfg = C.ENEMIES[en.type];
      const d = dist2D(en.x, en.z, pl.x, pl.z);
      const los = hasLOS(map, Math.floor(en.z), Math.floor(en.x), Math.floor(pl.z), Math.floor(pl.x));

      applyFlash(en);
      applyFlinch(en);

      if (!en.aggroed) {
        if (d < C.PLAYER.aggroRange && los) {
          en.aggroed = true;
          en.state = 'chase';
        } else {
          en.vx = 0;
          en.vz = 0;
        }
        animate(en, dt, false);
        setPos(en);
        continue;
      }

      en.state = 'chase';
      en.facing = Math.atan2(pl.z - en.z, pl.x - en.x);
      applyKnockback(en, dt);
      en.cooldown -= dt;

      const attacking = en.attackT > 0;
      let moving = false;

      if (en.type === 'demon') {
        if (d > cfg.rangeMax) { moving = true; steer(en, pl, dt, false); }
        else if (attacking) { en.vx *= 0.8; en.vz *= 0.8; }
        else if (en.cooldown <= 0) {
          en.cooldown = cfg.cooldown;
          en.attackT = 0.4; en.attackDur = 0.4;
          hooks.damagePlayer(R(cfg.damage, cfg.damage));
          hooks.meleeImpact(en.x, en.z);
        } else { moving = true; steer(en, pl, dt, false, 0.3); } // encosta devagar
      } else {
        if (d > cfg.rangeMax) { moving = true; steer(en, pl, dt, false); }
        else if (d < cfg.rangeMin) { moving = true; steer(en, pl, dt, true); } // recua p/ distância preferida
        else if (attacking) { en.vx *= 0.8; en.vz *= 0.8; }
        else if (en.cooldown <= 0) {
          en.cooldown = cfg.cooldown;
          if (en.type === 'zombie') {
            en.attackT = 0.55; en.attackDur = 0.55;
            if (hitscanZombie(en)) en.attackFlash = 0.12;
          } else if (en.type === 'imp') {
            en.attackT = 0.6; en.attackDur = 0.6;
            fireball(en);
          } else { // baron — tiro duplo
            en.attackT = 0.6; en.attackDur = 0.6;
            fireball(en);
            setTimeout(() => { if (!en.dead) fireball(en); }, 250);
          }
        } else { moving = true; strafeInPlace(en, pl, dt); }
      }

      if (!moving) { en.vx *= Math.max(0, 1 - 5 * dt); en.vz *= Math.max(0, 1 - 5 * dt); }
      separate(en, list, dt);
      animate(en, dt, moving);
      setPos(en);
    }
  }

  spawnFromMap();

  return {
    list,
    update,
    damageEnemy,
    get count() { return list.filter((e) => !e.dead).length; },
  };
}

export default createEnemies;
ENDOFENEMIES
